import json,datetime
from sam_common import ROOT,utc

def interval(row):return f'{100*row["delta"]:+.1f} [{100*row["ci"][0]:+.1f}, {100*row["ci"][1]:+.1f}]'
def main():
 d=ROOT/'battlelog1850';audit=json.loads((d/'integrity-audit.json').read_text());assert audit['passed'] and audit['games']==1600
 ranked=json.loads((d/'validation/singleton-ranking.json').read_text());order=json.loads((d/'validation/request-priority.json').read_text());summary=json.loads((d/'validation/summary.json').read_text());meta=json.loads((d/'manifest.json').read_text());inventory=json.loads((ROOT/'affordability-income.json').read_text());lookup={(r['candidate'],r['group']):r for r in summary}
